import{_ as s,o as t,c as a,ag as n}from"./chunks/framework.yGqRar0R.js";const h=JSON.parse('{"title":"vSLS commands","description":"","frontmatter":{},"headers":[],"relativePath":"guide/vsls/commands.md","filePath":"guide/vsls/commands.md"}'),o={name:"guide/vsls/commands.md"};function r(i,e,l,d,p,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="vsls-commands" tabindex="-1">vSLS commands <a class="header-anchor" href="#vsls-commands" aria-label="Permalink to &quot;vSLS commands&quot;">​</a></h1><p>Reference for the in-game <strong><code>/sls</code></strong> command tree. Unless noted, arguments are case-sensitive and must match the server or blueprint identifiers returned by the plugin.</p><h2 id="table-of-contents" tabindex="-1">Table of contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of contents&quot;">​</a></h2><ul><li><a href="#info">Info</a></li><li><a href="#list">List</a></li><li><a href="#create">Create</a></li><li><a href="#start">Start</a></li><li><a href="#pause">Pause</a></li><li><a href="#resume">Resume</a></li><li><a href="#restart">Restart</a></li><li><a href="#stop">Stop</a></li><li><a href="#kill">Kill</a></li><li><a href="#reset">Reset</a></li><li><a href="#join">Join</a></li><li><a href="#find">Find</a></li><li><a href="#delete">Delete</a></li><li><a href="#console">Console</a></li><li><a href="#logs">Logs</a></li><li><a href="#install">Install</a></li><li><a href="#blueprint">Blueprint</a></li><li><a href="#mixin">Mixin</a></li><li><a href="#node">Node</a></li><li><a href="#system">System</a></li><li><a href="#reload">Reload</a></li><li><a href="#status">Status</a></li><li><a href="#stats">Stats</a></li><li><a href="#debug">Debug</a></li><li><a href="#dequeue">Dequeue</a></li><li><a href="#version">Version</a></li><li><a href="#general-notes">General notes</a></li></ul><hr><h2 id="info" tabindex="-1">Info <a class="header-anchor" href="#info" aria-label="Permalink to &quot;Info&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code> (required for server-specific details)</p><p><strong>Description:</strong> Shows active servers and player counts, or detailed information for one server.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls info</span></span>
<span class="line"><span>/sls info &lt;server&gt;</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li><code>/sls info</code> — Lists active servers with player counts.</li><li><code>/sls info &lt;server&gt;</code> — Detailed view, including: <ul><li>Player count (hover for player names)</li><li>Status, blueprint id, blueprint type</li><li>Server software and version</li><li>Resource stats: CPU, memory (current / max and %), network in/out, uptime</li></ul></li></ul><hr><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p><strong>Permission:</strong> None</p><p><strong>Description:</strong> Lists every server vSLS knows about. Each line shows display name, status (by name color), and player count. Hover the name for the composite id; hover the player count for names on that server.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls list</span></span></code></pre></div><hr><h2 id="create" tabindex="-1">Create <a class="header-anchor" href="#create" aria-label="Permalink to &quot;Create&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Provisions a new server from a blueprint and starts it. Optional <code>key=value</code> flags override node, resources, software/image, and config patches.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls create &lt;blueprint_type&gt; &lt;blueprint_id&gt;</span></span>
<span class="line"><span>/sls create &lt;blueprint_type&gt; &lt;blueprint_id&gt; &lt;flags...&gt;</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>blueprint_type</code></td><td>Blueprint type (for example <code>minigame</code>, <code>adventure</code>, <code>pvp</code>).</td></tr><tr><td><code>blueprint_id</code></td><td>Specific blueprint id.</td></tr><tr><td><code>flags...</code></td><td>Optional space-separated overrides, each <code>--name=value</code> (see table below).</td></tr></tbody></table><p><strong>Override flags:</strong></p><table tabindex="0"><thead><tr><th>Flag</th><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><code>--node=</code></td><td>Node id</td><td>Create on this node; short ids resolve against the API node list.</td></tr><tr><td><code>--save=</code></td><td><code>true</code> / <code>false</code></td><td>Enable or disable saving for the instance.</td></tr><tr><td><code>--cpu=</code></td><td>Integer</td><td>CPU limit (percentage of CPU the instance may use).</td></tr><tr><td><code>--memory=</code></td><td>Integer</td><td>Memory limit in <strong>mebibytes (MiB)</strong>.</td></tr><tr><td><code>--swap=</code></td><td>Integer</td><td>Extra swap for the container.</td></tr><tr><td><code>--io_weight=</code></td><td>Integer</td><td>Relative I/O weight.</td></tr><tr><td><code>--disk_space=</code></td><td>Integer</td><td>Disk allowance in <strong>megabytes (MB)</strong>.</td></tr><tr><td><code>--threads=</code></td><td>String</td><td>CPU threads the Docker instance may use.</td></tr><tr><td><code>--oom_disabled=</code></td><td><code>true</code> / <code>false</code></td><td>If <code>true</code>, disables the OOM killer for the container.</td></tr><tr><td><code>--software=</code></td><td>String</td><td>Software id to run.</td></tr><tr><td><code>--version=</code></td><td>String</td><td>Software version.</td></tr><tr><td><code>--image=</code></td><td>String</td><td>Container image.</td></tr><tr><td><code>--seed=</code></td><td>String</td><td>Patches <code>server.properties</code>: <code>level-seed</code>.</td></tr><tr><td><code>--view-distance=</code></td><td>String</td><td>Patches <code>server.properties</code>: <code>view-distance</code>.</td></tr><tr><td><code>--enable-command-block=</code></td><td>String</td><td>Patches <code>server.properties</code>: <code>enable-command-block</code> (<code>true</code> / <code>false</code>).</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li>Tab completion for blueprint types and ids; after the id, completion can suggest flags, node ids, and boolean values where applicable.</li><li><code>--seed</code>, <code>--view-distance</code>, and <code>--enable-command-block</code> are merged into one config patch.</li><li>On success, the created server’s composite id is shown; failures print a reason.</li></ul><hr><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Starts an existing server that vSLS already tracks (for example after a stop, or when save kept the instance).</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls start &lt;server&gt;</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>server</code></td><td>Server id (short ids suggested by tab completion).</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li>Does not create a new instance from a blueprint — use <strong>Create</strong> or <strong>Join</strong> for that.</li><li>Fails with “No such server” if the id is unknown to vSLS.</li></ul><hr><h2 id="pause" tabindex="-1">Pause <a class="header-anchor" href="#pause" aria-label="Permalink to &quot;Pause&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Pauses a running server.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls pause</span></span>
<span class="line"><span>/sls pause &lt;server&gt;</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>With no argument (players only): pauses the SLS server the sender is currently on.</li><li>Console must pass <code>&lt;server&gt;</code>.</li></ul><hr><h2 id="resume" tabindex="-1">Resume <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Resume&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Resumes a paused server.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls resume</span></span>
<span class="line"><span>/sls resume &lt;server&gt;</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>With no argument (players only): resumes the SLS server the sender is currently on.</li><li>Console must pass <code>&lt;server&gt;</code>.</li></ul><hr><h2 id="restart" tabindex="-1">Restart <a class="header-anchor" href="#restart" aria-label="Permalink to &quot;Restart&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Restarts a server and queues connected players to rejoin when it reaches <strong>starting</strong>.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls restart</span></span>
<span class="line"><span>/sls restart &lt;server&gt;</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>With no argument (players only): restarts the SLS server the sender is currently on.</li><li>Players on the server get a title/chat notice and are reconnected when ready (status listener times out after about 2 minutes).</li><li>Console must pass <code>&lt;server&gt;</code>.</li></ul><hr><h2 id="stop" tabindex="-1">Stop <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;Stop&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Graceful shutdown for one server or all servers.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls stop</span></span>
<span class="line"><span>/sls stop &lt;server&gt;</span></span>
<span class="line"><span>/sls stop all</span></span>
<span class="line"><span>/sls stop &lt;server&gt; force</span></span>
<span class="line"><span>/sls stop all force</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><em>(none)</em></td><td>Players only: stop the SLS server the sender is on.</td></tr><tr><td><code>force</code></td><td>Unregister from vSLS even if shutdown fails.</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li>Without <code>force</code>, a failed shutdown can leave the server registered.</li><li><code>all</code> with no running servers prints an appropriate message.</li><li>Console must pass a server id or <code>all</code>.</li></ul><hr><h2 id="kill" tabindex="-1">Kill <a class="header-anchor" href="#kill" aria-label="Permalink to &quot;Kill&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Force-terminates a server (or all). Not a clean save; use <strong>Stop</strong> when you need a graceful exit.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls kill</span></span>
<span class="line"><span>/sls kill &lt;server&gt;</span></span>
<span class="line"><span>/sls kill all</span></span>
<span class="line"><span>/sls kill &lt;server&gt; force</span></span>
<span class="line"><span>/sls kill all force</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>Same <code>force</code> semantics as <strong>Stop</strong> for unregistering on partial failure.</li><li>With no argument (players only): kills the SLS server the sender is on.</li><li>Console must pass a server id or <code>all</code>.</li></ul><hr><h2 id="reset" tabindex="-1">Reset <a class="header-anchor" href="#reset" aria-label="Permalink to &quot;Reset&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Wipes saved overlay/world data for a server, then brings it back up and queues connected players to rejoin.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls reset</span></span>
<span class="line"><span>/sls reset &lt;server&gt;</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>Stops the instance, clears overlay upper/work data, starts again, and reconnects players when status becomes <strong>starting</strong>.</li><li>With no argument (players only): resets the server the sender is currently on.</li><li>Console must pass <code>&lt;server&gt;</code>.</li><li>Not every server can be reset; unsupported targets report an error.</li></ul><hr><h2 id="join" tabindex="-1">Join <a class="header-anchor" href="#join" aria-label="Permalink to &quot;Join&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code> to connect <strong>other</strong> players; joining <strong>yourself</strong> does not require admin.</p><p><strong>Description:</strong> Creates the server if needed, starts it, waits until status is <strong>ready</strong>, then moves the chosen player(s) to it. Or connect to the server a player is already on.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls join &lt;blueprint_type&gt; &lt;blueprint_id&gt;</span></span>
<span class="line"><span>/sls join &lt;blueprint_type&gt; &lt;blueprint_id&gt; [all | local | &lt;player&gt;]</span></span>
<span class="line"><span>/sls join player &lt;player&gt;</span></span>
<span class="line"><span>/sls join player &lt;player&gt; --force</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>blueprint_type</code>, <code>blueprint_id</code></td><td>Same as <strong>Create</strong>.</td></tr><tr><td><em>(none)</em></td><td>Connects the command sender.</td></tr><tr><td><code>all</code></td><td>Everyone on the proxy.</td></tr><tr><td><code>local</code></td><td>Everyone on the same backend server as the sender.</td></tr><tr><td><code>&lt;player&gt;</code></td><td>One player by username.</td></tr><tr><td><code>player &lt;player&gt;</code></td><td>Connects the sender to the vSLS server that player is on. Respects blueprint <code>matchmaking.maxPlayers</code> for normal players.</td></tr><tr><td><code>--force</code></td><td>Admin only (<code>sls.command.admin</code>). Bypasses blueprint capacity for <code>join player</code>.</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li>If an admin joins a player on a server already at <code>matchmaking.maxPlayers</code>, vSLS shows a warning with a <strong>Join Anyway</strong> option that runs <code>join player</code> with <code>--force</code> instead of blocking silently.</li></ul><hr><h2 id="find" tabindex="-1">Find <a class="header-anchor" href="#find" aria-label="Permalink to &quot;Find&quot;">​</a></h2><p><strong>Permission:</strong> None</p><p><strong>Description:</strong> Shows which vSLS server a player is currently on.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls find &lt;player&gt;</span></span></code></pre></div><hr><h2 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Permanently removes one server or every server vSLS tracks.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls delete</span></span>
<span class="line"><span>/sls delete &lt;server&gt;</span></span>
<span class="line"><span>/sls delete all</span></span>
<span class="line"><span>/sls delete &lt;server&gt; force</span></span>
<span class="line"><span>/sls delete all force</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>With no argument (players only): deletes the SLS server the sender is on.</li><li><code>force</code> continues local unregister when the remote delete fails.</li><li>Per-server results are reported.</li><li>Console must pass a server id or <code>all</code>.</li></ul><hr><h2 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Runs a line on a server console and tries to print captured output.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls console &lt;server&gt; &lt;command&gt;</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>server</code></td><td>Target server id.</td></tr><tr><td><code>command</code></td><td>Console line (arguments allowed). Leading <code>/</code> is stripped.</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li>Output is gathered by sampling logs with increasing delays (for example 100 ms / 8 lines, 800 ms / 12 lines, 3000 ms / 25 lines).</li><li>Errors are highlighted; if nothing is captured, you may see a “no output” style message.</li><li>Works with both legacy (<code>&gt;command</code>) and newer console formats.</li></ul><hr><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Shows paginated console log lines for a server.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls logs &lt;server&gt;</span></span>
<span class="line"><span>/sls logs &lt;server&gt; &lt;page&gt;</span></span>
<span class="line"><span>/sls logs &lt;server&gt; &lt;page&gt; &lt;lines&gt;</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>server</code></td><td>Server id, or <code>this</code> for the SLS server the sender is on.</td></tr><tr><td><code>page</code></td><td>Page number (default <code>1</code>).</td></tr><tr><td><code>lines</code></td><td>Lines per page (default <code>50</code>, max <code>1000</code>). Use <code>max</code> for the maximum.</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li>Framed output with a pagination footer.</li><li>Invalid page numbers report the valid range.</li></ul><hr><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Inspects or re-runs a server’s software install job (phase, container status, install logs, reinstall).</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls install info</span></span>
<span class="line"><span>/sls install info &lt;server&gt;</span></span>
<span class="line"><span>/sls install logs &lt;server&gt;</span></span>
<span class="line"><span>/sls install logs &lt;server&gt; &lt;page&gt;</span></span>
<span class="line"><span>/sls install logs &lt;server&gt; &lt;page&gt; &lt;lines&gt;</span></span>
<span class="line"><span>/sls install reinstall &lt;server&gt;</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>server</code></td><td>Server id, or <code>this</code> for the SLS server the sender is on.</td></tr><tr><td><code>page</code> / <code>lines</code></td><td>Same pagination rules as <strong>Logs</strong> for install log output.</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li><code>info</code> shows install phase, container status/name, exit code, timestamps, and failure reason when present.</li><li><code>info</code> with no server (players only) uses the sender’s current SLS server.</li><li><code>reinstall</code> triggers a new install run for that server.</li></ul><hr><h2 id="blueprint" tabindex="-1">Blueprint <a class="header-anchor" href="#blueprint" aria-label="Permalink to &quot;Blueprint&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Pretty-prints one blueprint (YAML-like layout with colored keys/values). Blueprints shown are <strong>resolved</strong> (mixin <code>includes</code> already applied).</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls blueprint &lt;blueprint_id&gt;</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>Field order matches the Protocube blueprint struct: <code>metadata</code>, <code>includes</code>, <code>server</code>, <code>state</code>, <code>save</code>, <code>annotations</code>.</li><li>Nested sections include limits, config patches, volumes, mounts, copy, and env.</li></ul><hr><h2 id="mixin" tabindex="-1">Mixin <a class="header-anchor" href="#mixin" aria-label="Permalink to &quot;Mixin&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Pretty-prints one mixin (YAML-like layout with colored keys/values). Mixins shown are <strong>resolved</strong> (<code>extends</code> chains already flattened).</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls mixin &lt;mixin_id&gt;</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>Field order matches the Protocube mixin struct: <code>mixin</code>, <code>extends</code>, <code>server</code>, <code>state</code>, <code>annotations</code>.</li><li>Tab completion suggests known mixin ids.</li></ul><hr><h2 id="node" tabindex="-1">Node <a class="header-anchor" href="#node" aria-label="Permalink to &quot;Node&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Inspects a daemon node and optionally reads or changes its <strong>drained</strong> flag. Drained nodes are excluded from provisioning: when drained is <code>true</code>, the load balancer does not start new servers on that node.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls node &lt;id&gt;</span></span>
<span class="line"><span>/sls node &lt;id&gt; drained</span></span>
<span class="line"><span>/sls node &lt;id&gt; drained &lt;true | false&gt;</span></span></code></pre></div><p><strong>Arguments:</strong></p><table tabindex="0"><thead><tr><th>Argument</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td>Node identifier. You may use a short id; it is resolved against the API’s node list (tab completion suggests shortened ids).</td></tr><tr><td><code>drained</code></td><td>Literal keyword. With no further argument, prints whether the node is currently drained (<code>true</code> or <code>false</code>).</td></tr><tr><td><code>true</code> or <code>false</code></td><td>Optional, after <code>drained</code>: updates the node’s drained state on the API.</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li><code>/sls node &lt;id&gt;</code> prints detailed information for the node, including: <ul><li><strong>Node metadata:</strong> name, location, URL, current drained flag, daemon version</li><li><strong>System:</strong> architecture, CPU threads, memory, kernel version, operating system and OS type</li><li><strong>Docker:</strong> engine version; when available, cgroup driver/version, container counts (total, running, paused, stopped), storage driver/filesystem, and runc version. If Docker details are missing, the command indicates that they are unavailable.</li></ul></li><li><code>/sls node &lt;id&gt; drained</code> displays only the drained state.</li><li><code>/sls node &lt;id&gt; drained &lt;true | false&gt;</code> sets the drained state and confirms the value that was sent.</li></ul><hr><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Prints Protocube version and host information (CPU threads, memory, kernel, OS).</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls system</span></span></code></pre></div><hr><h2 id="reload" tabindex="-1">Reload <a class="header-anchor" href="#reload" aria-label="Permalink to &quot;Reload&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Reloads vSLS config and/or asks Protocube to reload blueprints (and mixins) or software definitions.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls reload</span></span>
<span class="line"><span>/sls reload all</span></span>
<span class="line"><span>/sls reload config</span></span>
<span class="line"><span>/sls reload blueprints</span></span>
<span class="line"><span>/sls reload software</span></span></code></pre></div><p><strong>Modes:</strong></p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><em>(none)</em> or <code>all</code></td><td>Config + blueprints/mixins + software.</td></tr><tr><td><code>config</code></td><td>vSLS plugin config only.</td></tr><tr><td><code>blueprints</code></td><td>API reload on Protocube, then refetch and refresh the local blueprint <strong>and</strong> mixin registries.</td></tr><tr><td><code>software</code></td><td>API request to reload software configuration on Protocube.</td></tr></tbody></table><p><strong>Details:</strong></p><ul><li>Blueprint reload prints how many blueprints and mixins loaded.</li><li>Errors include failure reasons from the API or plugin.</li></ul><hr><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Shows a server’s lifecycle status from cache or from the node.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls status &lt;server&gt;</span></span>
<span class="line"><span>/sls status &lt;server&gt; remote</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>Without <code>remote</code>: last known status in vSLS.</li><li>With <code>remote</code>: status fetched via the API from the daemon.</li><li>Typical values include <code>offline</code>, <code>starting</code>, <code>running</code>, <code>stopping</code>.</li></ul><hr><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Resource snapshot for one server (CPU, memory, network, uptime) with human-readable units.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls stats &lt;server&gt;</span></span></code></pre></div><hr><h2 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code></p><p><strong>Description:</strong> Toggles extra debug messages for the executing player.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls debug</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>Players only (not console).</li><li>Toggles on/off per player.</li></ul><hr><h2 id="dequeue" tabindex="-1">Dequeue <a class="header-anchor" href="#dequeue" aria-label="Permalink to &quot;Dequeue&quot;">​</a></h2><p><strong>Permission:</strong> <code>sls.command.admin</code> to dequeue <strong>others</strong>; dequeuing <strong>yourself</strong> needs no admin node.</p><p><strong>Description:</strong> Removes the sender or selected players from matchmaking queues.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls dequeue</span></span>
<span class="line"><span>/sls dequeue [all | local | &lt;player&gt;]</span></span></code></pre></div><p><strong>Details:</strong></p><ul><li>Tab completion for player names where applicable.</li><li>Feedback includes the server/queue context when relevant.</li></ul><hr><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h2><p><strong>Permission:</strong> None</p><p><strong>Description:</strong> Prints vSLS version and author metadata.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sls version</span></span></code></pre></div><hr><h2 id="general-notes" tabindex="-1">General notes <a class="header-anchor" href="#general-notes" aria-label="Permalink to &quot;General notes&quot;">​</a></h2><ul><li>Commands that need <code>sls.command.admin</code> fail with a permission error if the sender lacks it.</li><li>Server ids must match exactly (case-sensitive); many commands accept short ids via tab completion.</li><li>Several server commands accept no id when run by a player on an SLS server (they target the current server). Console usually requires an explicit id.</li><li>Tab completion is available for commands.</li></ul>`,225)])])}const u=s(o,[["render",r]]);export{h as __pageData,u as default};
